<script lang="ts">
import{openHudLink}from './hud_links';
import{onMount}from 'svelte';import{invoke}from '@tauri-apps/api/core';
import type{HudProfile}from './launcher_plugins';
import type{OverlaySnapshot}from './launcher_extensions';
let{profile=$bindable(),onchange=()=>{},frame=null,preview=false}:{profile:HudProfile;onchange?:()=>void;frame?:OverlaySnapshot|null;preview?:boolean}=$props();
type Pack={name:string;enabled:boolean;order:number};type Content={resourcepacks:Pack[];shaderpacks:Pack[];servers:{name:string;address:string}[];options:Record<string,string>};
let content=$state<Content>({resourcepacks:[],shaderpacks:[],servers:[],options:{}}),message=$state(''),busy=$state(false),loaded=$state(false);
let values=$state<Record<string,number>>({fov:70,chunks:12,gamma:1,gui:0,volume:1,music:1,fps_limit:120});
async function refresh(){if(preview||!frame?.pid)return;busy=true;try{content=await invoke<Content>('hud_game_content',{pid:frame.pid});if(!loaded){const o=content.options;for(const[name,key]of Object.entries({chunks:'renderDistance',gamma:'gamma',gui:'guiScale',volume:'soundCategory_master',music:'soundCategory_music',fps_limit:'maxFps'})){const n=Number(o[key]);if(o[key]!=null&&Number.isFinite(n))values[name]=n;}if(o.fov!=null)values.fov=Math.round(Number(o.fov)*40+70);loaded=true;}}catch(error){message=String(error);}finally{busy=false;}}
onMount(()=>{void refresh();});
async function background(event:Event){const input=event.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file||!frame?.pid)return;if(file.size>20*1024*1024||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){message='Elige PNG, JPG, WebP o GIF de hasta 20 MB.';return;}busy=true;try{const bitmap=await createImageBitmap(file);if(bitmap.width>8192||bitmap.height>8192){bitmap.close();throw new Error('La imagen supera 8192 píxeles.');}const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d')!.drawImage(bitmap,0,0);bitmap.close();message=await invoke<string>('hud_menu_background',{pid:frame.pid,dataUrl:canvas.toDataURL('image/png')});}catch(e){message=String(e);}finally{busy=false;input.value='';}}

async function command(action:string,parameters:Record<string,string>={}){if(preview){message='Vista previa. Los controles se aplican con una partida abierta.';return;}if(!frame?.pid){message='Abre una partida desde TP LAUNCHER.';return;}busy=true;message='Esperando confirmación de Minecraft…';try{message=await invoke<string>('hud_game_command',{pid:frame.pid,action,values:parameters});if(['packs','shader'].includes(action))await refresh();if(action==='connect')await invoke('set_hud_interactive',{editing:false});}catch(error){message=String(error);}finally{busy=false;}}
function packs(){const selected=content.resourcepacks.filter(p=>p.enabled);void command('packs',Object.fromEntries(['vanilla',...selected.map(p=>'file/'+p.name)].map((name,i)=>['pack.'+i,name])));}
function move(i:number,delta:number){const rows=[...content.resourcepacks],target=i+delta;if(target<0||target>=rows.length)return;[rows[i],rows[target]]=[rows[target],rows[i]];content.resourcepacks=rows;}
async function shortcut(id:string){if(preview){message='El atajo se enviará únicamente a la ventana de Minecraft.';return;}try{await invoke('hud_debug_shortcut',{shortcut:id});}catch(error){message=String(error);}}
</script>
<section class="controls"><h3>Packs, shaders y control rápido</h3><p>Los cambios se aplican al proceso de Minecraft abierto. La compatibilidad se confirma con su adaptador.</p><div class="message" role="status">{message}</div>
<h4>Control de niebla</h4><label class="check"><input type="checkbox" bind:checked={profile.fog.enabled} onchange={()=>{const module=profile.modules.find(m=>m.id==='no_fog');if(module)module.enabled=profile.fog.enabled;onchange();}}/>Desactivar niebla en entornos seleccionados</label><div class="buttons">{#each [['overworld','Overworld'],['nether','Nether'],['end','The End'],['water','Agua'],['lava','Lava']] as [id,label]}<label class="check"><input type="checkbox" bind:checked={profile.fog[id as 'overworld'|'nether'|'end'|'water'|'lava']} onchange={onchange}/>{label}</label>{/each}</div><label>Reducción de niebla <output>{Math.round(profile.fog.strength*100)}%</output><input type="range" min="0" max="1" step=".05" bind:value={profile.fog.strength} oninput={onchange}/></label><small>Se aplica en vivo mediante los hooks de render compatibles. Los shaders que usan su propia niebla pueden requerir un adaptador específico.</small><h4>TP Turbo · próximo inicio</h4><label class="check"><input type="checkbox" bind:checked={profile.low_latency} onchange={onchange}/>Ajustes de recolección G1GC para Java 8 o superior</label><small>Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.</small><h4>Gráficos y audio</h4><div class="options">{#each [['fov','Campo de visión',30,110,1,'°'],['chunks','Distancia de renderizado',2,32,1,' chunks'],['gamma','Brillo',0,1,.05,''],['gui','Escala de interfaz (0: automática)',0,8,1,''],['fps_limit','Límite de FPS',10,260,10,''],['volume','Volumen general',0,1,.05,''],['music','Música',0,1,.05,'']] as [id,label,min,max,step,unit]}<label>{label}<output>{values[id as string]}{unit}</output><input type="range" {min} {max} {step} bind:value={values[id as string]} disabled={busy} onchange={()=>void command('option',{name:String(id),value:String(values[id as string])})}/></label>{/each}</div><small>El brillo respeta el rango admitido por el juego; no se promete Fullbright con una opción que Minecraft limita.</small>
<h4>Cambio rápido de servidor</h4><small>Conectar sale de la partida actual. Requiere TP Companion compatible.</small>{#each content.servers as server}<div class="pack"><span>{server.name}<small> · {server.address}</small></span><button disabled={busy||!frame?.telemetry?.capabilities.includes('controls')} onclick={()=>void command('connect',{address:server.address})}>Conectar</button></div>{/each}{#if !content.servers.length}<p>No hay servidores guardados en esta instancia.</p>{/if}<h4>Herramientas del juego</h4><div class="buttons">{#each [['hitboxes','Hitboxes · F3+B'],['chunks','Bordes de chunk · F3+G'],['clear_chat','Limpiar chat · F3+D'],['tooltips','Tooltips · F3+H'],['reload','Recargar recursos · F3+T']] as [id,label]}<button disabled={busy} onclick={()=>void shortcut(id)}>{label}</button>{/each}<button disabled={busy} onclick={()=>void command('memory_gc')}>Solicitar recolección de memoria</button></div><small>Los atajos devuelven el foco al juego. Algunos no existen en versiones antiguas. La JVM puede ignorar una solicitud de memoria.</small>
<div class="pack-heading"><h4>Paquetes de recursos</h4><button disabled={busy} onclick={()=>void refresh()}>Actualizar</button></div><small>La prioridad más alta aparece al final de la lista.</small>{#each content.resourcepacks as pack,i}<div class="pack"><label><input type="checkbox" bind:checked={pack.enabled} disabled={busy}/>{pack.name}</label><button aria-label={`Subir ${pack.name}`} disabled={busy||i===0} onclick={()=>move(i,-1)}>↑</button><button aria-label={`Bajar ${pack.name}`} disabled={busy||i===content.resourcepacks.length-1} onclick={()=>move(i,1)}>↓</button></div>{/each}{#if !content.resourcepacks.length}<p>No hay paquetes en la carpeta resourcepacks de esta instancia.</p>{/if}<button disabled={busy||!content.resourcepacks.length} onclick={packs}>Aplicar prioridad y recargar</button>
<h4>Fondo del menú principal · TP Companion</h4><label>Subir PNG, JPG, WebP o GIF<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" disabled={busy||preview||!frame?.telemetry?.capabilities.includes('controls')} onchange={background}/></label><small>El fondo queda en esta instancia; las animaciones usan el primer fotograma.</small><h4>Shaders instalados</h4><div class="buttons"><button disabled={busy} onclick={()=>void command('shader',{name:''})}>Desactivar shaders</button>{#each content.shaderpacks as pack}<button class:active={pack.enabled} disabled={busy} onclick={()=>void command('shader',{name:pack.name})}>{pack.name}</button>{/each}</div>{#if !content.shaderpacks.length}<p>No hay archivos en shaderpacks. La recarga necesita Iris u OptiFine compatible.</p>{/if}
<button onclick={()=>void openHudLink('https://modrinth.com/resourcepacks').catch(error=>message=String(error))}>Explorar más paquetes en Modrinth ↗</button></section>
<style>.controls{display:grid;gap:14px}.controls h3,.controls h4{margin:0}.controls p,.controls small{font-size:11px;line-height:1.6;color:#b7a9c2}.message{font-size:11px;color:#dab6f7;white-space:pre-line}.message:empty{display:none}.options{display:grid;grid-template-columns:1fr 1fr;gap:16px}.controls label{display:grid;gap:7px;font-size:11px}.controls output{color:#cfadf0}.controls input[type=range]{width:100%;accent-color:var(--hud-accent,#a855f7)}.buttons{display:flex;gap:7px;flex-wrap:wrap}.controls button{background:#ffffff08;color:inherit;border:1px solid #ffffff22;padding:9px;font:inherit;font-size:11px;cursor:pointer}.controls button:disabled{opacity:.4;cursor:default}.pack{display:flex;gap:7px;border:1px solid #ffffff15;padding:8px}.pack label{display:flex;align-items:center;gap:8px;flex:1;overflow-wrap:anywhere}.controls .check{display:flex;align-items:center;gap:8px}.pack-heading{display:flex;align-items:center;justify-content:space-between}.active{border-color:#a855f7!important}</style>
